'use strict';
const topics = {love:'爱情与关系',work:'事业与方向',lost:'此刻的迷茫',growth:'自我成长'};
const readings = [
  {id:'love-1',topic:'love',number:'零一',name:'花开有时',poem:['不催花开早','自有清风来'],title:'你值得被爱，<br>也值得慢慢来。',body:['也许你正在等一个回应，或努力猜测一段关系的方向。悬着的心会累，这份在意值得被温柔对待。','这支签想邀请你，把一点注意力放回自己。别人的回应不能替你定义价值；你可以期待靠近，也可以保留自己的节奏。'],action:'给自己写下一句：「在关系里，我希望被怎样对待？」只写一个最真实的需要就好。',time:'2 分钟',seal:'爱己'},
  {id:'love-2',topic:'love',number:'零二',name:'言暖如春',poem:['心事轻轻说','春风慢慢听'],title:'有些靠近，<br>从一句真心话开始。',body:['有时我们把想念藏进沉默，把委屈放进「没关系」。期待对方懂你，是很自然的心情。','不必一次说清所有感受。找一个让你安心的人，用一小句具体的话表达自己；表达的意义，是让你的需要也有一个位置。'],action:'把一件小事写成「当……时，我感到……，我希望……」。先写给自己看，愿意时再分享。',time:'3 分钟',seal:'坦然'},
  {id:'love-3',topic:'love',number:'零三',name:'留白有光',poem:['疏枝留月影','心宽纳微光'],title:'给关系一点空间，<br>也给自己一点安稳。',body:['当你很在意一个人，消息的空白也可能变得很响。你并没有因为敏感，就变得不值得喜欢。','今天可以试着不为每一段沉默写下结论。允许事情暂时没有答案，同时照顾好自己的生活；边界也可以是一种温柔。'],action:'给自己留出十分钟，把手机放远一点，泡一杯喜欢的饮品，认真感受第一口的温度。',time:'10 分钟',seal:'心安'},
  {id:'love-4',topic:'love',number:'零四',name:'相逢有暖',poem:['寻常一声问','也可暖人心'],title:'小小的善意，<br>也值得被看见。',body:['关系里的温暖，有时藏在很日常的地方：被记住的喜好、一句问候、一个愿意听你说话的人。','如果此刻身边有让你安心的人，可以把感谢具体地说出来。如果暂时没有，也可以先把这份温柔留给自己。'],action:'写下一件最近让你感到被照顾的小事。若愿意，把「谢谢你当时……」送给那个人。',time:'2 分钟',seal:'知暖'},
  {id:'work-1',topic:'work',number:'零五',name:'小步成途',poem:['不必一朝远','寸行亦成山'],title:'你不必一下子，<br>看见整条路。',body:['面对工作或方向的选择，想尽快确定答案很正常。但需要时间，和没有能力，是两回事。','今天先把宏大的问题缩小。一个可完成的动作，往往能带来比反复设想更多的信息；走过一点，路才会更清楚一点。'],action:'选一件拖着的小任务，只写下它的第一个动作。例如：打开文档，写一个标题。然后只做这一步。',time:'5 分钟',seal:'徐行'},
  {id:'work-2',topic:'work',number:'零六',name:'自有山海',poem:['各有行舟处','不争一水先'],title:'别人的进度，<br>不是你的刻度。',body:['看见别人向前，难免会怀疑自己是不是落后了。尤其在疲惫的时候，我们容易只看见别人的结果。','你的起点、资源和在意的事，都有自己的样子。把目光收回来一点，看看什么进展对你真正有意义。'],action:'写下这周你已经做成的一件小事，再补一句：「它为什么对我有意义？」不需要和任何人比较。',time:'3 分钟',seal:'自持'},
  {id:'work-3',topic:'work',number:'零七',name:'停舟听风',poem:['停舟非忘渡','蓄力待新潮'],title:'歇一歇，<br>也是照顾前行的自己。',body:['你可能已经努力很久了，却还在要求自己多撑一下。如果一直紧绷，连做过的事也容易看不见。','休息无需等到一切都完成。给今天划一个温柔的边界，让专注与恢复都有位置。'],action:'为今天剩下的工作选一个「到这里就好」的收尾点，把明天的第一步写下来，然后允许自己结束。',time:'3 分钟',seal:'从容'},
  {id:'work-4',topic:'work',number:'零八',name:'问路有声',poem:['一灯明一隅','相问路渐清'],title:'你可以借一盏灯，<br>再走自己的路。',body:['遇到不熟悉的事，不必要求自己全都独自弄明白。想寻求帮助，并不会抹去你已经付出的努力。','一次具体的提问，可能比「我要赶快变厉害」更容易开始。你可以吸收别人的经验，再决定哪些适合自己。'],action:'写下当前最卡住你的一个问题，并找一个可用的资料入口或能请教的人。今天先把问题问清楚。',time:'5 分钟',seal:'明途'},
  {id:'lost-1',topic:'lost',number:'零九',name:'雾散见山',poem:['且行一小步','山色自徐来'],title:'暂时没有答案，<br>也可以好好过今天。',body:['当很多事情都悬而未决，连最平常的一天也可能变得沉重。此刻的迷茫，不需要被急着修好。','先不替很远的未来作答。把今天握得住的一件小事做好，给自己一点落脚的地方；答案可以在生活里慢慢长出来。'],action:'看看身边，选一个很小的角落，用五分钟把它整理舒服一点。让此刻有一个可安放自己的地方。',time:'5 分钟',seal:'见山'},
  {id:'lost-2',topic:'lost',number:'一〇',name:'听心有声',poem:['风声暂且远','一念自心来'],title:'先听听自己，<br>真正需要什么。',body:['声音太多的时候，我们可能分不清「我想要」和「我应该」。你可以先让那些标准安静片刻。','今天不急着选出最完美的方向。辨认一种真实的感受，或一个眼下的需要，就已经在更靠近自己。'],action:'补完这句话：「如果暂时不考虑别人的期待，我今天最需要的是……」允许答案简单，也允许答案改变。',time:'2 分钟',seal:'听心'},
  {id:'lost-3',topic:'lost',number:'一一',name:'微光在侧',poem:['长夜非无色','微光在眼前'],title:'一点点明亮，<br>也能陪你走一段。',body:['你不必为了振作，假装眼前的困难不存在。那些累与不确定，都可以被承认。','与此同时，也许还能给一个细小的舒服留些位置：窗边的光、熟悉的味道，或有人认真听你说话。小小的好，并不要求你立刻变好。'],action:'找一件让感官舒服一点的小事：听一首喜欢的歌、看看窗外，或洗一把脸。只认真感受这一刻。',time:'3 分钟',seal:'微光'},
  {id:'lost-4',topic:'lost',number:'一二',name:'行处有径',poem:['未必知终点','可先试一程'],title:'把选择变小，<br>把空间留大。',body:['如果每个决定都像要定下一生，迈步当然会很难。许多方向，其实可以先做一次小小的尝试。','试过之后调整，也是一种了解自己的方式。你可以先收集感受，再决定要不要继续。'],action:'想一件最近好奇的事，设计一个十分钟、随时能停的小尝试。比如读两页介绍，或画一张粗略草图。',time:'10 分钟',seal:'试行'},
  {id:'growth-1',topic:'growth',number:'一三',name:'自有花期',poem:['不与春争早','一枝自有时'],title:'你有自己的花期，<br>也有自己的样子。',body:['成长有时很安静，安静到像什么都没发生。但那些重新尝试的时刻、逐渐认识自己的过程，也值得被记住。','你不必每天都比昨天更好。照顾当下的自己，也是成长可以有的样子。'],action:'写下一件过去不容易、现在稍微容易了一点的事。对那时努力过的自己说一句：「谢谢你。」',time:'3 分钟',seal:'花期'},
  {id:'growth-2',topic:'growth',number:'一四',name:'柔亦有力',poem:['柔枝承雨露','亦可向天青'],title:'对自己温柔一点，<br>并不会让你失去力量。',body:['也许你习惯用苛刻推动自己，害怕一放松就会停下来。那份想要做好的心，我们先好好接住。','试着换一种语气陪伴自己：承认哪里不容易，再给下一步留一点余地。温柔也可以很具体、很有行动力。'],action:'把最近对自己说过的一句责备，改写成你会对好朋友说的话。写下来，慢慢读一遍。',time:'3 分钟',seal:'温柔'},
  {id:'growth-3',topic:'growth',number:'一五',name:'减枝生新',poem:['枝疏风自入','心简见新芽'],title:'少做一件事，<br>也可以多一点自己。',body:['当「应该」排得满满的，自己的感受很容易被挤到最后。你不必靠事事答应，来证明自己的价值。','今天可以辨认一件不必承担的小事。给精力留一点空白，也是在认真对待你在意的生活。'],action:'看看今天的安排，选一件可以推迟、缩小或婉拒的小事。给省下的时间起个名字：「留给自己」。',time:'3 分钟',seal:'留白'},
  {id:'growth-4',topic:'growth',number:'一六',name:'初心如芽',poem:['小芽无声处','亦向日光生'],title:'给喜欢的事，<br>留一个小小的位置。',body:['忙着成为更好的自己时，我们有时忘了什么让自己感到鲜活。喜欢一件事，不一定需要成绩来证明。','你可以允许一点没有产出的快乐。它不必变成计划，只需要今天真实地陪你一小会儿。'],action:'找一件你曾经单纯喜欢的事，花五分钟重新碰一碰它：画几笔、翻一页书，或哼一段旋律。',time:'5 分钟',seal:'新芽'}
];
const $ = id => document.getElementById(id);
const STORAGE_KEY='yiqian.saved.v1';
let selectedTopic=null,currentReading=null,drawing=false,drawTimer=null,toastTimer=null;
let saved=[];
try {const parsed=JSON.parse(localStorage.getItem(STORAGE_KEY)||'[]');if(Array.isArray(parsed)){saved=parsed.filter(x=>x&&readings.some(r=>r.id===x.id)&&typeof x.date==='string'&&Number.isFinite(Date.parse(x.date))).map(x=>({id:x.id,date:x.date,done:!!x.done})).filter((x,i,a)=>a.findIndex(y=>y.id===x.id)===i).slice(0,16);}} catch {}
function landscape(kind='light') {
 const dark=kind==='dark',ink=dark?'#d0bd88':'#829177',pale=dark?'#b6b17e':'#b5bda1',sun=dark?'#ddc68d':'#bd7756';
 return `<svg viewBox="0 0 220 190" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><circle cx="94" cy="46" r="27" fill="${sun}" opacity=".75"/><path d="M15 132c22-29 35-39 55-26 14 9 29 19 43 14 30-12 37-7 69 11l24 12H15Z" fill="${pale}" opacity=".58"/><path d="M6 147c22-3 38-25 57-29 22-5 28 30 53 25 16-3 23-14 38-9 20 7 26 20 55 17v12H6Z" fill="${ink}" opacity=".42"/><g fill="none" stroke="${ink}" stroke-linecap="round" stroke-width="1.25"><path d="M19 171c39-10 66-6 95-4m-78 13c26-5 57-6 86-2m9-17 50 3m-41 9h57M34 137C53 99 53 61 38 31M46 84c-6-13-18-13-28-16m28 11c14-17 24-21 34-20M44 57c-8-8-15-9-24-9M48 101c15-10 23-10 30-9"/><path d="M135 43q8-6 16 0 8-6 16 0m-34 14q5-4 10 0 5-4 10 0" opacity=".6"/></g><g fill="${ink}" opacity=".85"><ellipse cx="23" cy="65" rx="4" ry="10" transform="rotate(-55 23 65)"/><ellipse cx="35" cy="73" rx="4" ry="11" transform="rotate(-36 35 73)"/><ellipse cx="62" cy="67" rx="4" ry="11" transform="rotate(40 62 67)"/><ellipse cx="75" cy="57" rx="4" ry="9" transform="rotate(60 75 57)"/><ellipse cx="25" cy="47" rx="4" ry="10" transform="rotate(-65 25 47)"/><ellipse cx="40" cy="38" rx="3" ry="10" transform="rotate(-22 40 38)"/><ellipse cx="65" cy="92" rx="4" ry="10" transform="rotate(65 65 92)"/></g><path d="m153 117 10-4 8 4-9 3Z" fill="${sun}" opacity=".7"/></svg>`;
}
$('hero-landscape').innerHTML=landscape();
function updateCount(){ $('saved-count').textContent=saved.length; $('saved-count').hidden=!saved.length; }
function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').classList.add('visible');toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3500);}
function persist(next){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(next));saved=next;updateCount();return true;}catch{toast('浏览器暂时无法保存。你仍可以在这里读完这张签。');return false;}}
function showView(id,title){for(const view of document.querySelectorAll('main>.view'))view.hidden=view.id!==id;window.scrollTo({top:0,behavior:'instant'});if(title)$(title).focus({preventScroll:true});}
function resetDraw(){clearTimeout(drawTimer);drawing=false;}
function goHome(){resetDraw();showView('choose-view','choose-title');}
function prepareDraw(){if(!selectedTopic)return;resetDraw();$('topic-label').textContent=topics[selectedTopic];$('draw-hint').textContent='没有选错的签，只有不同的看见。';$('pick-cards').innerHTML=['壹','贰','叁'].map((label,i)=>`<button class="pick-card" data-card="${i}" aria-label="抽取第${label}支签"><span class="pick-card-inner"><span class="card-mark">一念 · 一签</span><span class="card-symbol">签</span><small>心 诚 · 意 定</small><span class="card-mark">${label}</span></span></button>`).join('');showView('draw-view','draw-title');}
function chooseReading(){let pool=readings.filter(r=>r.topic===selectedTopic&&r.id!==currentReading?.id);const values=new Uint32Array(1);crypto.getRandomValues(values);return pool[Math.floor(values[0]/4294967296*pool.length)];}
function renderResult(reading){currentReading=reading;selectedTopic=reading.topic;const radio=document.querySelector(`input[name="concern"][value="${reading.topic}"]`);if(radio)radio.checked=true;$('start').disabled=false;
 $('reading-card').innerHTML=`<span class="reading-number">第 ${reading.number} 签</span><div class="reading-art">${landscape()}</div><h2>${reading.name}</h2><p class="poem">${reading.poem.join('<br>')}</p><span class="reading-seal">${reading.seal}</span>`;
 $('result-topic').textContent=topics[reading.topic];$('result-title').innerHTML=reading.title;$('reading-body').innerHTML=reading.body.map(t=>`<p>${t}</p>`).join('');$('action-text').textContent=reading.action;$('action-time').textContent=reading.time;
 const entry=saved.find(x=>x.id===reading.id);$('action-done').checked=entry?.done||false;$('done-note').hidden=!$('action-done').checked;updateSaveButton();showView('result-view','result-title');
}
function updateSaveButton(){const exists=saved.some(x=>x.id===currentReading?.id);$('save').classList.toggle('saved',exists);$('save').querySelector('span').textContent=exists?'已收进签笺':'收好这张签';$('save').setAttribute('aria-label',exists?'已收进签笺，点击打开我的签笺':'收好这张签');}
function drawCard(button){if(drawing||!selectedTopic)return;drawing=true;const result=chooseReading();for(const card of document.querySelectorAll('.pick-card')){card.disabled=true;card.classList.add(card===button?'chosen':'muted');}$('draw-hint').textContent='你的这一签，正在轻轻展开……';drawTimer=setTimeout(()=>{drawing=false;renderResult(result);},matchMedia('(prefers-reduced-motion: reduce)').matches?30:950);}
function formatDate(date){return new Date(date).toLocaleDateString('zh-CN',{month:'long',day:'numeric'});}
function renderJournal(){updateCount();$('journal-list').innerHTML=saved.length?saved.map(entry=>{const r=readings.find(r=>r.id===entry.id);return `<article class="saved-reading"><button class="saved-open" data-open="${r.id}" aria-label="重读${r.name}"><small>${topics[r.topic]} · ${formatDate(entry.date)}${entry.done?' · 已许下小小一步':''}</small><h3>${r.name}</h3><p>${r.poem.join('，')}</p></button><button class="delete-button" data-remove="${r.id}" aria-label="删除${r.name}">删除</button></article>`;}).join(''):`<div class="empty-journal"><svg class="icon"><use href="#i-book"/></svg><h3>这里，等一段温柔的回音。</h3><p>读完签后，点「收好这张签」。<br>以后想起时，随时回来看看。</p><button class="text-button" id="empty-start">去抽一支签 →</button></div>`;}
function openJournal(){renderJournal();$('journal-modal').showModal();}
document.querySelectorAll('input[name="concern"]').forEach(input=>input.addEventListener('change',()=>{selectedTopic=input.value;$('start').disabled=false;}));
$('start').addEventListener('click',prepareDraw);$('home').addEventListener('click',goHome);$('back').addEventListener('click',goHome);$('restart').addEventListener('click',goHome);$('another').addEventListener('click',prepareDraw);
$('pick-cards').addEventListener('click',event=>{const button=event.target.closest('[data-card]');if(button)drawCard(button);});
$('save').addEventListener('click',()=>{if(!currentReading)return;if(saved.some(x=>x.id===currentReading.id)){openJournal();return;}if(persist([{id:currentReading.id,date:new Date().toISOString(),done:$('action-done').checked},...saved])){updateSaveButton();toast('已收好。想起时，来「我的签笺」看看。');}});
$('action-done').addEventListener('change',()=>{$('done-note').hidden=!$('action-done').checked;if(saved.some(x=>x.id===currentReading?.id)){const ok=persist(saved.map(x=>x.id===currentReading.id?{...x,done:$('action-done').checked}:x));if(!ok){$('action-done').checked=!$('action-done').checked;$('done-note').hidden=!$('action-done').checked;}}});
$('journal-open').addEventListener('click',openJournal);$('about-open').addEventListener('click',()=>$('about-modal').showModal());
for(const dialog of document.querySelectorAll('dialog')){dialog.querySelector('[data-close]').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});}
$('journal-list').addEventListener('click',event=>{const open=event.target.closest('[data-open]'),remove=event.target.closest('[data-remove]');if(open){$('journal-modal').close();renderResult(readings.find(r=>r.id===open.dataset.open));}else if(remove){const id=remove.dataset.remove;if(persist(saved.filter(x=>x.id!==id))){renderJournal();updateSaveButton();$('journal-modal').querySelector('[data-close]').focus();toast('已从这台设备移除这张签。');}}else if(event.target.closest('#empty-start')){$('journal-modal').close();goHome();}});
window.addEventListener('storage',event=>{if(event.key===STORAGE_KEY||event.key===null){try{const parsed=JSON.parse(localStorage.getItem(STORAGE_KEY)||'[]');saved=Array.isArray(parsed)?parsed.filter(x=>x&&readings.some(r=>r.id===x.id)&&typeof x.date==='string'&&Number.isFinite(Date.parse(x.date))).map(x=>({id:x.id,date:x.date,done:!!x.done})).filter((x,i,a)=>a.findIndex(y=>y.id===x.id)===i).slice(0,16):[];updateCount();updateSaveButton();if($('journal-modal').open)renderJournal();}catch{}}});
updateCount();
